import{z as l,x as i,o as A,c as C,q as t,j as s,D as B,d as a,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"跨团队协作与案例","description":"","frontmatter":{"title":"跨团队协作与案例","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc2-cross-team-cases.md","filePath":"quant/rc2-cross-team-cases.md","lastUpdated":1791413859000}'),d={name:"quant/rc2-cross-team-cases.md"};function p(h,E,u,m,F,c){const r=i("Mermaid");return A(),C("div",null,[E[2]||(E[2]=t('<h1 id="跨团队协作与案例" tabindex="-1">跨团队协作与案例 <a class="header-anchor" href="#跨团队协作与案例" aria-label="Permalink to &quot;跨团队协作与案例&quot;">​</a></h1><div class="epigraph"><p>跨团队事故的共同死因很少是技术，是「我知道，但你不知道」；接口的工作就是把知道变成契约。</p><footer>—— 据站内数据版本化、研究模拟实盘隔离与特征存储三元组口径的案例整理</footer></div><p><a href="/quant/rc2-committee-process">上一课</a>把决策关进了流程，但流程到团队边界为止。研究的产出每天要穿过三只别人的手：数据组管清洗修正，执行组管成交成本，特征组管训练与服务共用的一切；每只手都按自己的节奏改东西，而研究结论建立在改动之前的快照上。本课用三个案例读接口怎么断、怎么接——死因落在接口条款上，不落在沟通态度上，这是<a href="/quant/research-postmortem">研究复盘</a>死因口径在协作层的用法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>团队内协作有评审、文档与委员会兜底，团队之间没有：各有各的优先级、发布节奏和对「改个小地方」的判断。研究侧的防御本能是「把一切搬进自己团队」，那是坏解法：自建全链等于把别人的正职做成自己的副业（回测框架一课的自建分账同样适用）。真正的缺口是<strong>接口契约</strong>：研究消费别人的产物时，引用什么、依赖什么、何时通知谁。三个案例各断一处。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="案例一-修正发布的连锁" tabindex="-1">案例一：修正发布的连锁 <a class="header-anchor" href="#案例一-修正发布的连锁" aria-label="Permalink to &quot;案例一：修正发布的连锁&quot;">​</a></h3><p>数据组按发布流程重传公司行动修正，复权因子变化，分位数全漂。断点：一半在研实验的配置里写的是「数据库当前状态」而非快照 ID——<a href="/quant/de-data-versioning">数据版本化</a>「修正走发布不覆盖、旧版本永不可变」保住了钉版本的实验，没钉的全部静默作废，两个已进定案材料。接法：一律引用快照 ID；发布通知带版本号与差异摘要，自动推送给引用旧版本的负责人。</p><p><span class="marginnote">数字实例看复权因子：某股票 10 送 10，复权因子一变，历史价格整体砍半——昨天分位数排在 80% 的量价特征，今天同样的原始数据算出来落在 40%。没钉快照的实验不是「数据更新了」，是「研究对象被无声换掉了」，而你只在三周后发现曲线不对劲时才知情。</span></p><h3 id="案例二-执行假设的分叉" tabindex="-1">案例二：执行假设的分叉 <a class="header-anchor" href="#案例二-执行假设的分叉" aria-label="Permalink to &quot;案例二：执行假设的分叉&quot;">​</a></h3><p>回测按历史滑点模型算的容量，与执行组 TCA 实测差出一截——判据还成立，按回测容量排的上线计划却全错。断点：成交假设是写死的默认值，执行侧的真实成本从不回流。接法：把<a href="/quant/research-sim-prod">研究、模拟、实盘隔离</a>的口径反向用——分叉用来校准回测假设，TCA 周报按品种回流给撮合器更新参数，更新走版本（<a href="/quant/bf-fill-simulation-deep">成交模拟的深化</a>的乐观偏差入口须声明参数版本）。</p><h3 id="案例三-特征契约的错位" tabindex="-1">案例三：特征契约的错位 <a class="header-anchor" href="#案例三-特征契约的错位" aria-label="Permalink to &quot;案例三：特征契约的错位&quot;">​</a></h3><p>特征组改清洗规则没 bump 版本，线上用新规则算特征、模型用旧规则训练，实盘与回测系统性偏移，查了两周。断点：特征存储的三元组（定义、数据版本、清洗规则）服务侧没有强制校验。接法：<a href="/quant/fml-feature-store-deep">特征存储的深入</a>的三元组哈希两端比对，不一致即拒绝出信号——错位从两周后发现的静默偏移，变成当天的硬错误。</p>',13)),(A(),s(o,null,{default:B(()=>[n(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20DT%5B%22%E6%95%B0%E6%8D%AE%E7%BB%84%EF%BC%9A%E4%BF%AE%E6%AD%A3%E2%86%92%E6%96%B0%E7%89%88%E6%9C%AC%E5%8F%91%E5%B8%83%22%5D%20--%3E%20CT%5B%22%E5%A5%91%E7%BA%A6%EF%BC%9A%E7%89%88%E6%9C%AC%E5%8F%B7%20%2B%20%E7%94%9F%E6%95%88%E6%97%A5%E6%9C%9F%20%2B%20%E5%B7%AE%E5%BC%82%E9%80%9A%E7%9F%A5%22%5D%0A%20%20EX%5B%22%E6%89%A7%E8%A1%8C%E7%BB%84%EF%BC%9ATCA%20%E5%AE%9E%E6%B5%8B%E5%9B%9E%E6%B5%81%22%5D%20--%3E%20CT%0A%20%20FT%5B%22%E7%89%B9%E5%BE%81%E7%BB%84%EF%BC%9A%E8%A7%84%E5%88%99%E6%94%B9%E5%8A%A8%20bump%20%E7%89%88%E6%9C%AC%22%5D%20--%3E%20CT%0A%20%20CT%20--%3E%20RS%5B%22%E7%A0%94%E7%A9%B6%E4%BE%A7%EF%BC%9A%E5%BC%95%E7%94%A8%E7%89%88%E6%9C%AC%20%E9%9D%9E%E6%9C%80%E6%96%B0%22%5D%0A%20%20RS%20--%3E%20CHK%7B%22%E4%B8%A4%E7%AB%AF%E5%93%88%E5%B8%8C%E6%A0%A1%E9%AA%8C%22%7D%0A%20%20CHK%20--%3E%7C%E4%B8%8D%E4%B8%80%E8%87%B4%7C%20BLK%5B%22%E6%8B%92%E7%BB%9D%E5%87%BA%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20CHK%20--%3E%7C%E4%B8%80%E8%87%B4%7C%20OK%5B%22%E7%BB%93%E8%AE%BA%E5%BB%BA%E7%AB%8B%E5%9C%A8%E5%A3%B0%E6%98%8E%E7%9A%84%E5%BF%AB%E7%85%A7%E4%B8%8A%22%5D%0A%20%20BLK%20--%3E%20FIX%5B%22%E4%BF%AE%E5%A4%8D%E5%90%8E%E9%87%8D%E8%B7%91%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("三个案例压成一条原则："),e("strong",null,"消费方引用版本，生产方发布变更，两端校验一致"),a("。引用版本免受静默变更（案例一）；实测回流持续校准假设（案例二）；两端校验把「应该一致」变成「不一致即报错」（案例三）。契约载荷里最易省略的一栏是"),e("strong",null,"生效日期"),a("：「下个版本改」在三个团队里是三个日期；缺生效日期的通知等于没有通知，对齐责任又回到口头同步。事故复盘照判据口径写：死因是「引用了最新而非版本」「缺生效日期」，不是「沟通不畅」——前者有条款可改，后者只有态度可叹。")],-1)),(A(),s(o,null,{default:B(()=>[n(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E8%B7%A8%E5%9B%A2%E9%98%9F%E5%BC%82%E5%B8%B8%EF%BC%9A%E4%B8%A4%E8%BE%B9%E5%AF%B9%E4%B8%8D%E4%B8%8A%22%5D%20--%3E%20Q1%7B%22%E5%BC%95%E7%94%A8%E7%9A%84%E6%98%AF%E5%BF%AB%E7%85%A7%20ID%20%E8%BF%98%E6%98%AF%E6%9C%80%E6%96%B0%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%9C%80%E6%96%B0%22%7C%20C1%5B%22%E6%A1%88%E4%BE%8B%E4%B8%80%E6%96%AD%E7%82%B9%EF%BC%9A%E9%92%89%E5%BF%AB%E7%85%A7%E5%B9%B6%E8%AE%A2%E9%98%85%E5%8F%91%E5%B8%83%E9%80%9A%E7%9F%A5%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%BF%AB%E7%85%A7%22%7C%20Q2%7B%22%E5%A5%91%E7%BA%A6%E8%BD%BD%E8%8D%B7%E5%90%AB%E7%94%9F%E6%95%88%E6%97%A5%E6%9C%9F%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20C2%5B%22%E8%A1%A5%E7%94%9F%E6%95%88%E6%97%A5%E6%9C%9F%E4%B8%8E%E9%80%9A%E7%9F%A5%E6%B8%A0%E9%81%93%22%5D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20Q3%7B%22%E4%B8%A4%E7%AB%AF%E4%B8%89%E5%85%83%E7%BB%84%E5%93%88%E5%B8%8C%E4%B8%80%E8%87%B4%EF%BC%9F%22%7D%0A%20%20Q3%20--%3E%7C%22%E5%90%A6%22%7C%20C3%5B%22%E8%A7%84%E5%88%99%E6%94%B9%E5%8A%A8%E6%9C%AA%20bump%20%E7%89%88%E6%9C%AC%20%E6%8B%92%E7%BB%9D%E5%87%BA%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20Q3%20--%3E%7C%22%E6%98%AF%22%7C%20C4%5B%22%E6%9F%A5%E6%88%90%E4%BA%A4%E5%81%87%E8%AE%BE%EF%BC%9ATCA%20%E5%8F%82%E6%95%B0%E6%98%AF%E5%90%A6%E5%9B%9E%E6%B5%81%E6%A0%A1%E5%87%86%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">这张图回答的问题与上图不同：上图是「接口该怎么建」，这张是「异常已经发生，按哪条条款归因」。直觉类比：生效日期就是把「下周大扫除」改成「10 月 1 日大扫除」——三个室友嘴里的「下周」是三个日子，日历上的日期只有一个。</span></p><p><span class="marginnote">实用断点检测：盘点上游依赖里写「最新」「当前」「线上库」的引用，每个都是案例一的候选断点——盘点不过一小时，漏掉一个就是一次静默作废的金额。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>契约不是合同：接口靠共同利益与复盘维系，条款要少而硬——版本、生效日期、通知渠道，三条之外别贪。版本引用有代价：永远钉旧快照的研究会与现役系统脱节，重估与迁移是显式动作。三个案例是接缝的类型学（数据、执行、特征），不是全集；新断点按同样口径归档，类型学自己生长。</p><p><span class="marginnote">常见误区：初学者容易以为接口问题靠「多沟通、多对齐会」解决。口头约定是存在人脑里的一次性内存——三个月后没人记得当时说的是哪个版本；契约把承诺写进系统，「不一致即报错」不依赖任何人的记性。沟通仍需要，但用来谈条款，不用来当条款。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>团队间没有评审与委员会兜底，接口只能靠契约：消费方引用版本，生产方发布变更，两端校验。</li><li>案例一断在「引用最新」，快照与通知保住实验；案例二断在假设不回流，TCA 校准成交参数。</li><li>案例三断在三元组错位，两端哈希校验，不一致即拒绝出信号。</li><li>契约最易省略的栏是生效日期；死因落条款不落态度，复盘才能改东西。</li><li>出处：站内<a href="/quant/de-data-versioning">数据版本化</a>、<a href="/quant/research-sim-prod">研究、模拟、实盘隔离</a>、<a href="/quant/fml-feature-store-deep">特征存储的深入</a>、<a href="/quant/bf-fill-simulation-deep">成交模拟的深化</a>各课口径的案例整理。</li></ul>',7))])}const q=l(d,[["render",p]]);export{D as __pageData,q as default};
